import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { join } from "node:path";
import test from "node:test";
import { HARNESS_NAMES } from "./defaults.ts";
import { commonBody, defaultSourcesRoot, loadHarnessSources, overlayBody, renderOverlay } from "./prompt.ts";

test("every parent harness name has a SOURCE profile and listed overlay files exist", () => {
	const loaded = loadHarnessSources();
	assert.ok(loaded.length > 0);
	const claimed = new Set<string>();
	for (const source of loaded) {
		assert.equal(source.family, source.dir.split("/").at(-1));
		assert.match(source.ref.rev, /^[0-9a-f]{40}$/);
		if (source.shared) {
			assert.equal(existsSync(join(source.dir, source.shared)), true, source.shared);
		}
		for (const [name, profile] of Object.entries(source.profiles)) {
			assert.equal(claimed.has(name), false, `duplicate profile ${name}`);
			claimed.add(name);
			if (profile.overlay) {
				assert.equal(existsSync(join(source.dir, profile.overlay)), true, profile.overlay);
			}
		}
	}
	assert.deepEqual([...claimed].sort(), [...HARNESS_NAMES].sort());
});

test("family shared overlays prepend their profile extras", () => {
	const grok = overlayBody("grok-build");
	assert.match(grok, /Match the user's intent/);
	assert.doesNotMatch(grok, /\n\n/);
	assert.match(overlayBody("grok-build"), /ask_user_question/);
	assert.match(overlayBody("grok-build-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("grok-build-plan"), /not perform it/);
	assert.doesNotMatch(overlayBody("grok-build-plan"), /then implement/);

	const codex = overlayBody("codex");
	assert.match(codex, /sharing the user's workspace/);
	assert.match(codex, /Default collaboration mode/);
	assert.match(codex, /Follow the Clarity precheck in AGENTS.md/);
	assert.match(codex, /Cancellation or missing answers are not consent/);
	assert.match(codex, /Use plain-text questions only when ask_user_question is unavailable/);
	for (const name of ["codex", "grok-build", "zcode", "qwen-code"] as const) {
		const body = overlayBody(name);
		assert.match(body, /load clarify-request only when its conditional loading gate is met/);
		assert.match(body, /dependent follow-ups/);
		assert.doesNotMatch(body, /Ask once|only for optional questions|continue with best judgment/);
	}
	assert.match(overlayBody("codex-plan"), /sharing the user's workspace/);
	assert.match(overlayBody("codex-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("codex-plan"), /decision-complete/);

	const zcode = overlayBody("zcode");
	assert.match(zcode, /long-horizon/);
	assert.match(zcode, /ask_user_question/);
	assert.match(zcode, /path:line/);
	assert.match(zcode, /Do not retry the same call verbatim/);
	assert.match(overlayBody("zcode-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("zcode-plan"), /not perform it/);
	assert.match(overlayBody("zcode-plan"), /genuine fork/);
	assert.doesNotMatch(overlayBody("zcode-plan"), /then implement/);

	const qwen = overlayBody("qwen-code");
	assert.match(qwen, /Do not revert or overwrite unrelated user work/);
	assert.match(qwen, /ask_user_question/);
	assert.match(qwen, /path:line/);
	assert.match(qwen, /Do not retry the same call verbatim/);
	assert.doesNotMatch(qwen, /\n\n/);
	assert.match(overlayBody("qwen-code-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("qwen-code-plan"), /not perform it/);
	assert.match(overlayBody("qwen-code-plan"), /what existing code to reuse/);
	assert.doesNotMatch(overlayBody("qwen-code-plan"), /exit_plan_mode/);
	assert.doesNotMatch(overlayBody("qwen-code-plan"), /then implement/);

	const deepseek = overlayBody("deepseek-standard");
	assert.match(deepseek, /Ground work in the repository/);
	assert.doesNotMatch(deepseek, /You are a coding agent/);
	assert.doesNotMatch(deepseek, /\bgrep\b/);
	assert.match(deepseek, /lsp_navigation/);
	assert.match(deepseek, /external, untrusted data/);
	assert.match(overlayBody("deepseek-plan"), /Plan mode until the harness changes/);
	assert.match(overlayBody("deepseek-plan"), /decision-complete/);
	assert.doesNotMatch(overlayBody("deepseek-plan"), /exit_plan_mode/);
	assert.match(overlayBody("deepseek-minimal"), /deliberately small tool surface/);
});

test("renderOverlay wraps the body in a harness tag", () => {
	const rendered = renderOverlay({ name: "grok-build", source: "session" });
	assert.equal(rendered.startsWith("<harness>"), true);
	assert.equal(rendered.endsWith("</harness>"), true);
	assert.doesNotMatch(rendered, /name=|model=|thinking=/);
	assert.ok(rendered.includes(overlayBody("grok-build")));
});

test("default sources root sits next to prompt.ts", () => {
	assert.equal(defaultSourcesRoot().endsWith("/extensions/easy-harness/sources"), true);
});

test("the common layer follows every non-plan overlay and skips plan modes", () => {
	const common = commonBody();
	assert.match(common, /Think concisely/);
	assert.ok(overlayBody("deepseek-minimal").endsWith(common));
	assert.ok(overlayBody("grok-build").endsWith(common));
	for (const plan of ["deepseek-plan", "codex-plan", "grok-build-plan", "zcode-plan", "qwen-code-plan"] as const) {
		assert.doesNotMatch(overlayBody(plan), /Think concisely/);
	}
	assert.doesNotMatch(overlayBody("deepseek-minimal", undefined, false), /Think concisely/);
	assert.ok(renderOverlay({ name: "codex", source: "session" }).includes(common));
});

