export const COMMON_FILE = "common.md";

export function commonBody(root = defaultSourcesRoot()): string {
	const path = join(root, COMMON_FILE);
	return existsSync(path) ? readFileSync(path, "utf8").trim() : "";
}

/** Plan parents and plan roles skip the common layer: their job is a plan that covers edge cases
 *  and failure modes, which "think concisely" works against. */
export function isPlanName(name: string): boolean {
	return name.endsWith("-plan");
}

export function overlayBody(name: HarnessName, root?: string, common = true): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		if (common && !isPlanName(name)) parts.push(commonBody(root));
		return parts.filter(Boolean).join("\n");
	}
	throw new Error(`No overlay source for harness ${name}`);
}

