function registerSubagentOverlay(pi: ExtensionAPI, harnessName: HarnessName | typeof PI_DEFAULT): void {
	registerCapturePrune(pi);
	const capturePrompt = registerPromptCapture(pi);
	pi.on("before_agent_start", async (event, ctx) => {
		const resolved: ResolvedHarness | undefined = isPiDefault(harnessName)
			? undefined
			: {
					name: harnessName,
					model: ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : undefined,
					thinking: pi.getThinkingLevel() as ThinkingLevel,
					source: "session",
				};
		const overlay = resolved ? renderOverlay(resolved) : "";
		const effectiveSystemPrompt =
			overlay && !event.systemPrompt.includes(OVERLAY_MARK)
				? `${event.systemPrompt}\n\n${overlay}`
				: event.systemPrompt;
		if (loadSessionCaptureEnabled()) {
			const { sessionId, ephemeral } = captureSessionMeta(ctx, process.env.PI_SUBAGENT_PARENT_SESSION_ID);
			capturePrompt({
				sessionId,
				captureSubdir: process.env.PI_SUBAGENT_CAPTURE_SUBDIR,
				cwd: ctx.cwd,
				trusted: ctx.isProjectTrusted(),
				harnessName,
				harnessOverlay: overlay,
				effectiveSystemPrompt,
				model: ctx.model,
				thinking: String(pi.getThinkingLevel()),
				ephemeral,
			});
		}
		if (effectiveSystemPrompt === event.systemPrompt) return;
		return { systemPrompt: effectiveSystemPrompt };
	});

