export function familySharedBody(family: string, root?: string): string {
	for (const source of sources(root)) {
		if (source.family !== family) continue;
		return readOptional(source.dir, source.shared);
	}
	return "";
}

export function overlayBody(name: HarnessName, root?: string): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		return parts.filter(Boolean).join("\n");
	}
	throw new Error(`No overlay source for harness ${name}`);
}

export function renderOverlay(resolved: ResolvedHarness, root?: string): string {
	return `<harness>
${overlayBody(resolved.name, root)}
</harness>`;
}

edits.newText:
export function familySharedBody(family: string, root?: string): string {
	for (const source of sources(root)) {
		if (source.family !== family) continue;
		return readOptional(source.dir, source.shared);
	}
	return "";
}

/** The cross-family layer, `sources/common.md`: local guidance, not upstream text. Missing file = no layer. */
export const COMMON_FILE = "common.md";

export function commonBody(root = defaultSourcesRoot()): string {
	const path = join(root, COMMON_FILE);
	return existsSync(path) ? readFileSync(path, "utf8").trim() : "";
}

/** Plan parents and plan roles skip the common layer: a plan must cover edge cases and failure modes. */
export function isPlanName(name: string): boolean {
	return name.endsWith("-plan");
}

export function overlayBody(name: HarnessName, root?: string, common = true): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		if (common && !isPlanName(name)) parts.push(commonBody(root));
		return parts.filter(Boolean).join("\n");
	}
	throw new Error(`No overlay source for harness ${name}`);
}

export function renderOverlay(resolved: ResolvedHarness, root?: string, common = true): string {
	return `<harness>
${overlayBody(resolved.name, root, common)}
</harness>`;
}

