export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	/** Append `sources/common.md` after the role. Off for plan roles and when the common layer is disabled. */
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	const common = input.common ? commonBody(input.root) : "";
	const commonFiles = common ? [COMMON_FILE] : [];
	const withCommon = (text: string) =>
		common && !text.includes(common) ? [text, common].filter(Boolean).join("\n") : text;
	if (!shared) {
		return {
			family: input.family,
			text: withCommon(rolePrompt),
			files: [...(rolePrompt ? ["role"] : []), ...commonFiles],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: withCommon(rolePrompt),
			files: [`${input.family}/shared.md`, "role", ...commonFiles],
		};
	}
	const text = withCommon([shared, rolePrompt].filter(Boolean).join("\n"));
	return {
		family: input.family,
		text,
		files: [`${input.family}/shared.md`, ...(rolePrompt ? ["role"] : []), ...commonFiles],
	};
}

