types.ts:40: export interface HarnessConfig {

export type ThinkingLevel = "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max";

export type HarnessFamily = "grok-build" | "codex" | "zcode" | "qwen-code" | "deepseek";

export type HarnessName =
	| "grok-build"
	| "grok-build-plan"
	| "codex"
	| "codex-plan"
	| "zcode"
	| "zcode-plan"
	| "qwen-code"
	| "qwen-code-plan"
	| "deepseek-minimal"
	| "deepseek-standard"
	| "deepseek-plan";

/** Model grade for one harness. Same shape as settings.json agentOverrides. */
export interface HarnessGrade {
	model: string;
	thinking: ThinkingLevel;
}

export type HarnessSelection = HarnessName | "pi-default";

/** A picker row: a parent harness, `off` (automatic selection off, no overlay), or `on` (route by model). */
export type HarnessPickerValue = HarnessName | "off" | "on";

/** Result of the `/harness` picker dialog. `saveAsDefault` marks a Ctrl+S selection. */
export interface HarnessPickerResult {
	value: HarnessPickerValue;
	saveAsDefault: boolean;
}

export interface HarnessRoute {
	match: readonly string[];
	harness: HarnessSelection;
}

export interface HarnessConfig {
	default?: HarnessSelection;
	/** `false` turns off automatic harness selection: no model routing, no startup default. */
	auto?: boolean;
	routes: readonly HarnessRoute[];
	grades: Partial<Record<HarnessName, HarnessGrade | false>>;
	sessionCapture?: boolean;
	subagents?: boolean;
	/** Prepend family shared.md onto offload workers. Default off. */
	offload?: boolean;
}

export interface ResolvedHarness {
	name: HarnessName;
	model?: string;
	provider?: string;
	modelId?: string;
	thinking?: ThinkingLevel;
	source: "session" | "default" | "config";
}

export interface ModelRef {
	provider: string;
	id: string;
}

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { DEFAULT_HARNESS_CONFIG, HARNESS_FAMILIES, PI_DEFAULT, isHarnessName, isPiDefault } from "./defaults.ts";
import { parseOnOff } from "./session-capture.ts";
import type { HarnessConfig, HarnessGrade, HarnessName, HarnessSelection, ThinkingLevel } from "./types.ts";

const THINKING = new Set<ThinkingLevel>(["off", "minimal", "low", "medium", "high", "xhigh", "max"]);

export function configPath(): string {
	return join(homedir(), ".pi", "agent", "config.jsonc");
}

export function parseHarnessConfig(value: unknown): HarnessConfig {
	if (!isRecord(value)) return { routes: [], grades: {} };
	const grades: HarnessConfig["grades"] = {};
	const routes = parseRoutes(value.routes);
	let fallback: HarnessSelection | undefined;
	let sessionCapture: boolean | undefined;
	let subagents: boolean | undefined;
	let offload: boolean | undefined;
	let auto: boolean | undefined;
	for (const [key, raw] of Object.entries(value)) {
		if (key === "auto") {
			auto = !(raw === false || raw === "off" || raw === "false");
			continue;
		}
		if (key === "sessionCapture" || key === "capture") {
			sessionCapture = parseOnOff(raw);
			continue;
		}
		if (key === "subagents") {
			subagents = parseOnOff(raw);
			continue;
		}
		if (key === "offload") {
			offload = parseOnOff(raw);
			continue;
		}
		if (key === "default") {
			if (typeof raw === "string" && (isPiDefault(raw) || isHarnessName(raw))) {
				fallback = isPiDefault(raw) ? PI_DEFAULT : raw;
			}
			continue;
		}
		if (key === "routes") continue;
		if (!isHarnessName(key)) continue;
		if (raw === false) {
			grades[key] = false;
			continue;
		}
		const grade = parseGrade(raw);
		if (grade) grades[key] = grade;
	}
	const parsed: HarnessConfig = { routes, grades };
	if (fallback) parsed.default = fallback;
	if (auto !== undefined) parsed.auto = auto;
	if (sessionCapture !== undefined) parsed.sessionCapture = sessionCapture;
	if (subagents !== undefined) parsed.subagents = subagents;
	if (offload !== undefined) parsed.offload = offload;
	return parsed;
}

export function loadSessionCaptureEnabled(path = configPath()): boolean {
	return loadHarnessConfig(path).sessionCapture === true;
}

export function loadSubagentHarnessEnabled(path = configPath()): boolean {
	const raw = readRawConfigFile(path);
	const workloads = raw && isRecord(raw.workloads) ? raw.workloads : undefined;
	const subagents = workloads && isRecord(workloads.subagents) ? workloads.subagents : undefined;
	if (subagents?.promptAssembly !== undefined) return subagents.promptAssembly === "child-harness";
	return loadHarnessConfig(path).subagents === true;
}

export function loadOffloadHarnessEnabled(path = configPath()): boolean {
	const raw = readRawConfigFile(path);
	const workloads = raw && isRecord(raw.workloads) ? raw.workloads : undefined;
	const offload = workloads && isRecord(workloads.offload) ? workloads.offload : undefined;
	if (offload?.promptProfile !== undefined) return offload.promptProfile === "model-family";
	return loadHarnessConfig(path).offload === true;
}

export function mergeHarnessConfig(...layers: HarnessConfig[]): HarnessConfig {
	const merged: HarnessConfig = { routes: [], grades: {} };
	for (const layer of layers) {
		if (layer.default) merged.default = layer.default;
		if (layer.auto !== undefined) merged.auto = layer.auto;
		if (layer.sessionCapture !== undefined) merged.sessionCapture = layer.sessionCapture;
		if (layer.subagents !== undefined) merged.subagents = layer.subagents;
		if (layer.offload !== undefined) merged.offload = layer.offload;
		merged.routes = [...layer.routes, ...merged.routes];
		for (const [name, grade] of Object.entries(layer.grades) as Array<
			[HarnessName, HarnessGrade | false | undefined]
		>) {
			if (grade === undefined) continue;
			if (grade === false) {
				merged.grades[name] = false;
				continue;
			}
			const prev = merged.grades[name];
			merged.grades[name] = { ...(typeof prev === "object" ? prev : {}), ...grade };
		}
	}
	return merged;
}

export function loadHarnessConfig(path = configPath()): HarnessConfig {
	return mergeHarnessConfig(DEFAULT_HARNESS_CONFIG, readConfigFile(path) ?? { routes: [], grades: {} });
}

function readRawConfigFile(path: string): Record<string, unknown> | undefined {
	if (!existsSync(path)) return undefined;
	try {
		const raw = JSON.parse(stripJsonc(readFileSync(path, "utf8")));
		return isRecord(raw) ? raw : undefined;
	} catch {
		return undefined;
	}
}

